"""Splitting money between parties."""

from collections.abc import Sequence


def _plain_split(total: int, weights: Sequence[int], active: list[int]) -> dict[int, int]:
    """Split `total` over the `active` indices in proportion to their weights (largest remainder)."""
    weight_sum = sum(weights[i] for i in active)
    shares = {i: 0 for i in active}
    if weight_sum == 0:
        return shares
    fractions = {}
    for i in active:
        numerator = total * weights[i]
        shares[i] = numerator // weight_sum
        fractions[i] = numerator % weight_sum
    leftover = total - sum(shares.values())
    # Stable sort keeps original order among equal remainders.
    order = sorted(active, key=lambda i: -fractions[i])
    for i in order[:leftover]:
        shares[i] += 1
    return shares


def allocate(total: int, weights: Sequence[int], caps: Sequence[int] | None = None) -> list[int]:
    """Split `total` cents in proportion to `weights`. See README.md for the rules."""
    if total < 0:
        raise ValueError("total must not be negative")
    if len(weights) == 0:
        raise ValueError("weights must not be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must not be negative")
    if sum(weights) == 0:
        raise ValueError("weights must not all be zero")
    if caps is not None:
        if len(caps) != len(weights):
            raise ValueError("caps must have one entry per weight")
        if any(c < 0 for c in caps):
            raise ValueError("caps must not be negative")

    positive = [i for i, w in enumerate(weights) if w > 0]

    if caps is None:
        shares = _plain_split(total, weights, positive)
        return [shares.get(i, 0) for i in range(len(weights))]

    if sum(caps[i] for i in positive) < total:
        raise ValueError("caps cannot hold the total")

    result = [0] * len(weights)
    active = list(positive)
    remaining = total
    while True:
        shares = _plain_split(remaining, weights, active)
        over = [i for i in active if shares[i] > caps[i]]
        if not over:
            for i in active:
                result[i] = shares[i]
            return result
        for i in over:
            result[i] = caps[i]
            remaining -= caps[i]
        active = [i for i in active if i not in over]
